<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import { base } from '$app/paths';
  import { t, language } from './i18n';
  import { subscriptionLocales } from './subscription-format';
  export let tenant: string;
  export let apiPrefix = '';
  export let number = '';
  type ProviderName = 'meta' | 'twilio';
  type Provider = {enabled:boolean;configured:boolean;state:string;recipients:string[];missing_settings:string[];invalid_settings:string[]};
  type Plan = {id:string;name:string;monthly_pence:number;setup_pence:number;message_usage_model?:string};
  type Billing = {kind:string;plan:Plan|null;allowance:{used:number;paused:boolean}|null;usage_credit?:{available_pence:number;reserved_pence:number;spent_pence:number;unknown_reservations:number;paused:boolean};ai_processing_paused?:boolean;vat_percent?:number};
  type Status = {ready:boolean;tenant_active:boolean;subscription_enabled:boolean;blockers:{code:string;action:string}[];providers:{meta:Provider;twilio:Provider};setup?:{webhook_url:string;status_callback_url:string;public_https:boolean};billing?:Billing;voice:{configured:boolean;ready:boolean;compressed_audio_supported:boolean;bounded_audio_model:boolean;missing_settings:string[];invalid_settings:string[]}};
  let status: Status|null = null;
  let provider: ProviderName = 'meta';
  let providerChosen = false;
  let busy = false;
  let error = '';
  let copied = '';
  let copyLabel = '';
  let numberType = 'existing';
  let disposed = false;
  let controller: AbortController | undefined;
  const stateNames:Record<string,string> = {disabled:'Not enabled on this platform',unassigned:'Number still needs assigning',missing_settings:'Provider details needed',invalid_configuration:'Settings need correcting',configured:'Local settings ready'};
  const settingNames:Record<string,string> = {WHATSAPP_APP_SECRET:'Meta app secret',WHATSAPP_TOKEN:'Meta access token',WHATSAPP_VERIFY_TOKEN:'Webhook verification token',WHATSAPP_PHONE_ID:'Meta phone number ID',WHATSAPP_API_URL:'Meta API address',TWILIO_AUTH_TOKEN:'Twilio auth token',TWILIO_WHATSAPP_NUMBER:'Twilio WhatsApp sender number',OPENAI_API_KEY:'AI provider key'};
  const blockerNames:Record<string,string> = {whatsapp_not_configured:'Configure an enabled provider and assign its recipient to this company.',tenant_inactive:'Complete company activation.',whatsapp_subscription_inactive:'Activate WhatsApp access for this company.',whatsapp_allowance_exhausted:'The legacy message allowance is exhausted. Review your subscription.'};
  $: money = (pence:number) => new Intl.NumberFormat(subscriptionLocales[$language],{style:'currency',currency:'GBP',minimumFractionDigits:2,maximumFractionDigits:2}).format(pence/100);
  $: count = (value:number) => new Intl.NumberFormat(subscriptionLocales[$language]).format(value);
  const link = (section:string) => base+'/'+section+'?tenant='+encodeURIComponent(tenant);
  $: providerName = provider === 'meta' ? 'Meta' : 'Twilio';
  $: selected = status?.providers[provider];
  $: hasRecipient = Boolean(selected?.recipients.length);
  $: providerReady = Boolean(status?.ready && selected?.configured && status.setup?.public_https);
  $: completed = status ? [hasRecipient,Boolean(selected?.configured),status.tenant_active && status.subscription_enabled,Boolean(status.setup?.public_https)].filter(Boolean).length : 0;
  $: normalizedNumber = normalizeNumber(number);
  $: validNumber = /^\+[1-9]\d{6,14}$/.test(normalizedNumber);
  $: chatLink = validNumber ? 'https://wa.me/'+normalizedNumber.substring(1) : '';
  onMount(() => { void load(); });
  onDestroy(() => { disposed = true; controller?.abort(); });
  function normalizeNumber(value:string) {
    return value.trim().replace(/[٠-٩۰-۹]/g, digit => String(digit.charCodeAt(0) - (digit <= '٩' ? 0x660 : 0x6f0))).replace(/[\s()-]/g,'');
  }
  async function load() {
    if (busy || disposed) return;
    const request = new AbortController(); controller = request;
    busy = true; error = ''; copied = '';
    const timeout = setTimeout(() => request.abort(), 15000);
    try {
      const response = await fetch(apiPrefix+'/admin/api/integrations?tenant='+encodeURIComponent(tenant), {credentials:'same-origin',signal:request.signal});
      if (!response.ok) throw new Error(response.status === 401 ? 'Your session expired. Sign in again.' : 'Could not load WhatsApp setup. Try refreshing.');
      const data = await response.json();
      if (disposed || request.signal.aborted) return;
      if (data.tenant !== tenant || !data.whatsapp?.providers?.meta || !data.whatsapp?.providers?.twilio) throw new Error('Could not load WhatsApp setup. Try refreshing.');
      status = data.whatsapp;
      if (!providerChosen && status) provider = status.providers.twilio.configured && !status.providers.meta.configured ? 'twilio' : status.providers.meta.enabled ? 'meta' : 'twilio';
    } catch (failure) {
      if (!disposed && controller === request) error = request.signal.aborted ? 'Loading timed out. Try refreshing.' : failure instanceof Error && failure.message === 'Your session expired. Sign in again.' ? failure.message : 'Could not load WhatsApp setup. Try refreshing.';
    } finally { clearTimeout(timeout); if (!disposed && controller === request) busy = false; }
  }
  async function copy(value:string, label:string) {
    try { await navigator.clipboard.writeText(value); if (!disposed) { copied = '{label} copied.'; copyLabel = label; } }
    catch { if (!disposed) copied = 'Copy is unavailable. Select the text and copy it manually.'; }
  }
  function chooseProvider(value:ProviderName) {
    provider = value; providerChosen = true; copied = '';
    if (value === 'meta' && numberType === 'sandbox') numberType = 'existing';
  }
  function settingLabel(setting:string, translate:typeof $t) { return translate(settingNames[setting] || 'Provider setting'); }
  function blockerLabel(code:string, translate:typeof $t) { return translate(blockerNames[code] || 'Review the provider settings before launch.'); }
  function setupSummary(translate:typeof $t, current:Status|null, chosen:Provider|undefined, currentTenant:string, chosenProvider:ProviderName, phone:string, phoneValid:boolean) {
    if (!current || !chosen) return '';
    return [translate('WhatsApp setup for {tenant}',{tenant:currentTenant}),translate('Provider: {provider}',{provider:chosenProvider === 'meta' ? 'Meta' : 'Twilio'}),translate('Assigned recipients: {recipients}',{recipients:chosen.recipients.join(', ')||translate('Not assigned')}),...(phoneValid ? [translate('Customer-facing number: {number}',{number:phone})] : []),translate('Incoming webhook: {url}',{url:current.setup?.webhook_url||translate('Awaiting public server address')}),...(chosenProvider === 'twilio' ? [translate('Status callback: {url}',{url:current.setup?.status_callback_url||translate('Awaiting public server address')})] : []),translate(stateNames[chosen.state]||'Check settings'),...current.blockers.map(item=>translate(blockerNames[item.code]||'Review the provider settings before launch.')),translate('Keep provider tokens and secrets in protected server settings.')].join('\n');
  }
  $: summary = setupSummary($t,status,selected,tenant,provider,normalizedNumber,validNumber);
</script>

<section class="whatsapp" lang={$language} dir={$language==='ar'?'rtl':'ltr'} aria-labelledby="whatsapp-setup-title">
  <header class="intro"><div><p class="eyebrow">{$t('Customer channels')} · <bdi>{tenant}</bdi></p><h2 id="whatsapp-setup-title">{$t('WhatsApp, ready for your business')}</h2><p>{$t('Choose your connection, prepare your number and see what you will pay before launch.')}</p></div><button class="secondary" type="button" disabled={busy} on:click={load}>{$t(busy ? 'Checking…' : 'Refresh setup')}</button></header>
  {#if error}<p class="notice error" role="alert">{$t(error)}</p>{/if}
  {#if !status && !error}<p class="loading" role="status"><span aria-hidden="true"></span>{$t('Loading your WhatsApp setup…')}</p>{/if}
  {#if status && selected}
    <div class="readiness" class:ready={providerReady}>
      <div><span class="status-dot" aria-hidden="true"></span><strong>{$t(providerReady ? 'Local setup ready — test before launch' : status.billing?.allowance?.paused ? 'WhatsApp paused — monthly allowance reached' : 'Let’s finish your setup')}</strong><p>{$t('{count}/4 local checks complete for {provider}. Delivery still needs a real message test.',{count:count(completed),provider:providerName})}</p></div>
      <div class="check-pills"><span class:done={hasRecipient}>{hasRecipient ? '✓' : '○'} {$t('Number assigned')}</span><span class:done={selected.configured}>{selected.configured ? '✓' : '○'} {$t('Provider settings')}</span><span class:done={status.tenant_active && status.subscription_enabled}>{status.tenant_active && status.subscription_enabled ? '✓' : '○'} {$t('V7 access')}</span><span class:done={status.setup?.public_https}>{status.setup?.public_https ? '✓' : '○'} {$t('Public HTTPS')}</span></div>
    </div>
    <nav class="step-nav" aria-label={$t('WhatsApp setup steps')}><a href="#whatsapp-number">01 · {$t('Number & provider')}</a><a href="#whatsapp-connect">02 · {$t('Connection')}</a><a href="#whatsapp-costs">03 · {$t('Costs')}</a><a href="#whatsapp-test">04 · {$t('Test & launch')}</a></nav>
    <article class="panel" id="whatsapp-number">
      <div class="panel-heading"><span class="step-number" aria-hidden="true">01</span><div><h3>{$t('Choose how to connect')}</h3><p>{$t('These buttons change the guide shown here. The platform operator saves the actual connection.')}</p></div></div>
      <div class="provider-picker" aria-label={$t('Provider setup guides')}>
        <button class:chosen={provider === 'meta'} aria-pressed={provider === 'meta'} on:click={()=>chooseProvider('meta')}><strong>Meta Cloud API</strong><span>{$t('Connect directly through Meta')}</span><small>{$t(stateNames[status.providers.meta.state]||'Check settings')}</small></button>
        <button class:chosen={provider === 'twilio'} aria-pressed={provider === 'twilio'} on:click={()=>chooseProvider('twilio')}><strong>Twilio</strong><span>{$t('Connect through your Twilio account')}</span><small>{$t(stateNames[status.providers.twilio.state]||'Check settings')}</small></button>
      </div>
      <div class="number-layout">
        <div><h4>{$t('Your customer-facing number')}</h4><label for="whatsapp-number-type">{$t('Which number will you use?')}<select id="whatsapp-number-type" bind:value={numberType}><option value="existing">{$t('A number I already own')}</option><option value="new">{$t('A new business number')}</option>{#if provider === 'twilio'}<option value="sandbox">{$t('Twilio Sandbox for testing')}</option>{/if}</select></label>
          <p>{$t(numberType === 'sandbox' ? 'Use Twilio’s shared test sender and follow its tester join instructions. A sandbox is not a production number; charges and restrictions apply.' : numberType === 'new' ? 'Choose a provider-compatible business number. Renting or buying a number is separate from V7 and may have recurring charges.' : 'Use a number you control. If it is already on WhatsApp, check the provider’s migration or coexistence process before changing anything.')}</p>
          <label for="whatsapp-number-check">{$t('Check number format')}<input id="whatsapp-number-check" type="tel" dir="ltr" bind:value={number} on:input={()=>copied=''} placeholder="+44 7700 900123" autocomplete="tel" maxlength="40" /></label><p class="hint">{$t('Include the country code. For a UK mobile, replace the first 0 with +44. This helper does not register or change a number.')}</p>
          {#if number}<p class="number-result" class:invalid={!validNumber} role="status">{#if validNumber}{$t('International format')}: <bdi>{normalizedNumber}</bdi>{:else}{$t('Enter +, the country code and the number, for example +44 7700 900123.')}{/if}</p>{/if}
          {#if validNumber}<div class="links"><button class="secondary" on:click={()=>copy(normalizedNumber,'Phone number')}>{$t(copied==='{label} copied.' && copyLabel==='Phone number'?'Number copied ✓':'Copy formatted number')}</button><button class="secondary" on:click={()=>copy(chatLink,'WhatsApp chat link')}>{$t(copied==='{label} copied.' && copyLabel==='WhatsApp chat link'?'Link copied ✓':'Copy chat link')}</button><a href={chatLink} target="_blank" rel="noopener noreferrer">{$t('Open chat')} ↗</a></div><p class="hint">{$t('Opening the link does not send a message. Confirm this is your approved business number before sharing it.')}</p>{/if}
        </div>
        <div class="assigned"><h4>{$t(provider==='meta'?'Assigned Meta phone number IDs':'Assigned WhatsApp sender numbers')}</h4>{#if selected.recipients.length}<ul class="recipient-list">{#each selected.recipients as recipient}<li><code dir="ltr">{provider === 'twilio' ? '+'+recipient : recipient}</code>{#if provider === 'twilio'}<button class="secondary" on:click={()=>number='+'+recipient}>{$t('Use this number')}</button>{/if}</li>{/each}</ul>{:else}<p class="empty">{$t('No number assigned to {tenant} yet.',{tenant})}</p>{/if}<p class="hint">{$t(provider==='meta'?'The phone number ID comes from Meta’s API setup. It is different from the phone number and the WhatsApp Business Account ID.':'This is the sender V7 uses to route incoming messages to this company. Entering a different number in the helper does not change that assignment.')}</p></div>
      </div>
      <details><summary>{$t('What must the number support?')}</summary><p>{$t('You must control the number and be able to complete the provider’s SMS or voice verification. Provider eligibility and approval apply. Keep an existing WhatsApp account and messages until the provider confirms the appropriate migration process.')}</p></details>
    </article>
    <article class="panel" id="whatsapp-connect">
      <div class="panel-heading"><span class="step-number" aria-hidden="true">02</span><div><h3>{$t('Connect {provider} to V7',{provider:providerName})}</h3><p>{$t('Provider account setup comes first. V7 then routes that sender to this company.')}</p></div><span class="badge" class:complete={selected.configured}>{$t(stateNames[selected.state]||'Check settings')}</span></div>
      <ol class="connection-steps">
        <li>{$t(provider==='meta'?'Prepare the sender in Meta. Verify your business number, then find its phone number ID in API setup.':'Register your WhatsApp sender in Twilio. Complete sender approval, or use the sandbox for a limited test.')}</li>
        <li>{$t('Ask your platform operator to save the provider credentials securely and assign the sender to {tenant}.',{tenant})}</li>
        <li>{$t(provider==='meta'?'Set the incoming webhook in your Meta app with the matching verification token and WhatsApp message event subscription.':'Configure incoming messages with HTTP POST to the webhook below. Use the status callback for signed delivery notifications.')}</li>
      </ol>
      {#if provider === 'meta'}<div class="notice"><strong>{$t('Meta account and payments')}</strong><p>{$t('Open your own business portfolio, select the WhatsApp Business Account for this number and manage its payment method, invoices and spending in Meta. V7 AI top-ups do not fund that account. Only authorised business administrators should change payment details.')}</p><p>{$t('V7 checks its local configuration only; it cannot verify your Meta payment method, balance or business approval. Complete those checks in Meta before testing delivery.')}</p><div class="links"><a href="https://business.facebook.com/" target="_blank" rel="noopener noreferrer">{$t('Open Meta Business Suite')} ↗</a><a href="https://developers.facebook.com/apps/" target="_blank" rel="noopener noreferrer">{$t('Open Meta app setup')} ↗</a></div></div>{/if}
      <div class="callback-grid"><div><label>{$t('Incoming-message webhook')}<input readonly dir="ltr" value={status.setup?.webhook_url||''} placeholder={$t('Available after public HTTPS server setup')} spellcheck="false" /></label><button class="secondary" disabled={!status.setup?.webhook_url} on:click={()=>copy(status!.setup!.webhook_url,'Webhook URL')}>{$t(copied==='{label} copied.' && copyLabel==='Webhook URL'?'Webhook copied ✓':'Copy webhook URL')}</button></div>{#if provider === 'twilio'}<div><label>{$t('Delivery-status callback')}<input readonly dir="ltr" value={status.setup?.status_callback_url||''} placeholder={$t('Available after public HTTPS server setup')} spellcheck="false" /></label><button class="secondary" disabled={!status.setup?.status_callback_url} on:click={()=>copy(status!.setup!.status_callback_url,'Status callback URL')}>{$t(copied==='{label} copied.' && copyLabel==='Status callback URL'?'Status URL copied ✓':'Copy status URL')}</button><p class="hint">{$t('V7 accepts signed callbacks; it does not currently show a delivery receipt timeline.')}</p></div>{/if}</div>
      <p class="hint">{$t('Use these exact URLs. Provider secrets belong in protected server settings, never in chat, your website code or a QR code.')}</p>
      {#if status.setup && !status.setup.public_https}<p class="notice">{$t('The operator needs to configure a public HTTPS server address before provider callbacks can reach V7.')}</p>{/if}
      {#if !selected.enabled}<p class="notice">{$t('This provider is disabled in the platform settings. Ask the operator to enable it, or use the other available provider.')}</p>{/if}
      {#if selected.missing_settings.length || selected.invalid_settings.length}<div class="notice"><strong>{$t('What the operator still needs to fix')}</strong><ul>{#each selected.missing_settings as setting}<li>{$t('Add {setting}.',{setting:settingLabel(setting,$t)})}</li>{/each}{#each selected.invalid_settings as setting}<li>{$t('Correct {setting}.',{setting:settingLabel(setting,$t)})}</li>{/each}</ul></div>{/if}
      <div class="links"><a href={provider==='meta'?'https://developers.facebook.com/docs/whatsapp/cloud-api/get-started':'https://www.twilio.com/docs/whatsapp/self-sign-up'} target="_blank" rel="noopener noreferrer">{$t('Official {provider} setup guide',{provider:providerName})} ↗</a><button class="secondary" on:click={()=>copy(summary,'Setup summary')}>{$t(copied==='{label} copied.' && copyLabel==='Setup summary'?'Setup summary copied ✓':'Copy setup summary for your operator')}</button></div>
      <details><summary>{$t('Technical settings & setup summary')}</summary><p>{$t('Assigned recipients are scoped to this company. This dashboard checks required server settings without displaying their secret values.')}</p><p>{$t('Missing')}: <code dir="ltr">{selected.missing_settings.join(', ')||$t('None')}</code>. {$t('Invalid')}: <code dir="ltr">{selected.invalid_settings.join(', ')||$t('None')}</code>.</p><label>{$t('Safe setup summary')}<textarea readonly value={summary} rows="8" spellcheck="false"></textarea></label></details>
    </article>
    <article class="panel" id="whatsapp-costs">
      <div class="panel-heading"><span class="step-number" aria-hidden="true">03</span><div><h3>{$t('Know the costs before you launch')}</h3><p>{$t('Your V7 subscription and your provider’s bill are separate.')}</p></div></div>
      <div class="cost-grid">
        <div class="cost-card"><p class="cost-label">{$t('V7 subscription')}</p>{#if status.billing?.kind==='internal'}<h4>{$t('Internal workspace')}</h4><p>{$t('No V7 customer subscription is required for this company.')}</p>{:else if status.billing?.kind==='tiered' && status.billing.plan}<h4><bdi>{status.billing.plan.name}</bdi> · {$t('WhatsApp included')}</h4><p class="cost-value"><bdi>{money(status.billing.plan.monthly_pence)}</bdi><span>{$t(status.billing?.vat_percent ? 'per month before VAT' : 'per month')}</span></p>{#if status.billing.vat_percent!=null}<p><strong>{$t(status.billing?.vat_percent ? '{price} / month including {percent}% VAT' : '{price} / month — no VAT charged',{price:money(Math.round(status.billing.plan.monthly_pence*(1+status.billing.vat_percent/100))),percent:count(status.billing.vat_percent)})}</strong></p>{/if}<p>{$t('AI processing is paid separately through prepaid usage credit. Phone numbers are not included.')}</p><p class="hint">{$t(status.billing?.vat_percent ? '{price} one-time setup before VAT' : '{price} one-time setup',{price:money(status.billing.plan.setup_pence)})} {#if status.billing.vat_percent!=null}{$t(status.billing?.vat_percent ? '{price} setup including {percent}% VAT' : '{price} setup — no VAT charged',{price:money(Math.round(status.billing.plan.setup_pence*(1+status.billing.vat_percent/100))),percent:count(status.billing.vat_percent)})}{/if} {$t('Provider setup prices are before discounts. Your saved discount and final invoice amounts appear in Subscription.')}</p>{:else if status.billing?.kind==='legacy'}<h4>{$t('Existing contract')}</h4><p>{$t('Your recorded subscription keeps its original terms. Check Subscription for the WhatsApp add-on and invoices.')}</p>{:else}<h4>{$t('Choose your V7 plan')}</h4><p>{$t('Starter, Business and Scale include WhatsApp access. You still need an approved provider connection and active company.')}</p>{/if}<p class="hint">{$t('V7 does not supply a phone number. Bring a number you control or arrange one separately; rental, purchase and provider messaging charges are not included.')}</p><a href={link('subscription')}>{$t('View plan & invoices')} →</a></div>
        <div class="cost-card"><p class="cost-label">{$t('{provider} provider bill',{provider:providerName})}</p><h4>{$t('Check your provider’s rates')}</h4><p>{$t(provider==='meta'?'Rates depend on message category, recipient market and current Meta rules.':'Twilio charges for incoming and outgoing messages, with applicable Meta fees added. Number rental and other account services can cost extra.')}</p><p class="hint">{$t('V7 usage credit does not pay your provider bill. Check the provider’s currency, taxes and account balance.')}</p><a href={provider==='meta'?'https://business.whatsapp.com/products/platform-pricing':'https://www.twilio.com/en-us/whatsapp/pricing'} target="_blank" rel="noopener noreferrer">{$t('Current {provider} rates',{provider:providerName})} ↗</a></div>
        <div class="cost-card"><p class="cost-label">{$t('AI usage credit')}</p>{#if status.billing?.kind==='internal'}<h4>{$t('Internal workspace')}</h4><p>{$t('Recorded model usage for the internal agent. Provider funding and availability still apply.')}</p>{:else}<h4>{$t('AI processing paid separately with prepaid usage credit')}</h4>{#if status.billing?.usage_credit}{@const wallet=status.billing.usage_credit}<p class="cost-value"><bdi>{money(wallet.available_pence)}</bdi><span>{$t('Available credit')}</span></p><p>{$t('{reserved} reserved · {spent} confirmed AI spend',{reserved:money(wallet.reserved_pence),spent:money(wallet.spent_pence)})}</p>{#if wallet.unknown_reservations}<p class="hint">{$t('{count} requests have an unconfirmed cost. Their reservations stay held while usage is reconciled.',{count:count(wallet.unknown_reservations)})}</p>{/if}{:else}<p>{$t('Your business owner can view detailed usage credit and top up in Subscription.')}</p>{/if}<p>{$t(status.billing?.ai_processing_paused?'Paid AI is paused until sufficient usage credit is available. Saved business knowledge remains available.':'Website and WhatsApp AI replies share a separate prepaid usage-credit balance. Incoming message counts are activity records, not a separate message-count allowance.')}</p>{#if status.billing?.allowance}<p class="hint">{$t('{count} incoming WhatsApp messages recorded this month. This is activity, not a message-count allowance.',{count:count(status.billing.allowance.used)})}</p>{/if}<p class="hint">{$t('Purchased credit carries forward. There is no automatic recharge, and credit is added only after Stripe confirms payment. At low credit, top up manually; when credit cannot cover a request, paid AI pauses and saved-knowledge replies remain available.')}</p><a href={link('subscription')}>{$t('View usage credit and top up')} →</a>{/if}</div>
      </div>
      <p class="cost-example">{$t('For example: three customer messages and three replies can create AI token charges in V7 and separate messaging charges from your provider.')}</p>
      <details><summary>{$t('Replies, templates and the 24-hour window')}</summary><p>{$t('V7 replies to incoming customer messages. A customer message opens the provider’s 24-hour service window; messages outside it generally need an approved template. Campaigns and template sending are not enabled by this setup. Provider pricing rules still apply.')}</p></details>
    </article>
    <article class="panel" id="whatsapp-test">
      <div class="panel-heading"><span class="step-number" aria-hidden="true">04</span><div><h3>{$t('Test the experience, then share the number')}</h3><p>{$t('Confirm the real customer journey before launch.')}</p></div></div>
      {#if status.blockers.length}<div class="notice"><strong>{$t('Finish these local checks first')}</strong><ul>{#each status.blockers as blocker}<li>{blockerLabel(blocker.code,$t)}</li>{/each}</ul><a href={link('subscription')}>{$t('Review company activation & WhatsApp access')} →</a></div>{/if}
      <ol class="connection-steps"><li>{$t('Refresh after the operator saves your settings. Check the sender is assigned to this company and V7 access is active.')}</li><li>{$t('Send a simple message from another phone. Ask about a saved product, opening hours or contact details. Testing can consume AI credit and incur provider charges.')}</li><li>{$t('Check the reply and the correct company. Review Conversations in V7 and delivery information in your provider account. If no reply arrives, check Errors & health and provider logs.')}</li><li>{$t('Share the approved number after testing. A link or QR opens chat; it does not pair or connect the agent.')}</li></ol>
      <div class="links"><a href={link('conversations')}>{$t('Conversations')} →</a><a href={link('errors')}>{$t('Errors & health')} →</a><a href={link('whatsapp-qr')+'#whatsapp-share'}>{$t('Create a link or QR')} →</a></div>
      <details><summary>{$t('Voice messages')}</summary><p>{$t(status.voice.ready?'Voice transcription is ready for local testing.':'Voice transcription still needs provider, decoder or AI setup.')}</p><p>{$t(status.voice.compressed_audio_supported?'Compressed voice recordings can be decoded on this server. Paid transcription is limited to 60 seconds and requires provider funding and sufficient AI credit.':'Compressed voice decoding is unavailable on this server. Ask customers to type instead; paid transcription accepts supported PCM WAV audio up to 60 seconds.')}</p><p>{$t('The agent sends text replies. Test voice-message delivery before launch.')}</p>{#if status.voice.missing_settings.length || status.voice.invalid_settings.length}<p>{$t('Operator checklist')}: {status.voice.missing_settings.concat(status.voice.invalid_settings).map(setting=>settingLabel(setting,$t)).join(', ')}.</p>{/if}</details>
    </article>
    {#if copied}<p class="copy-status" role="status">{$t(copied,{label:$t(copyLabel)})}</p>{/if}
  {/if}
</section>

<style>
